import React, { useState, useEffect } from 'react';
import Sidebar from '../components/Sidebar';
import Header from '../components/Header';
import api from '../services/api';
import { UserPlus, Edit, Trash2, X } from 'lucide-react';

const Faculty = () => {
  const [faculty, setFaculty] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [selectedFaculty, setSelectedFaculty] = useState(null);
  const [formData, setFormData] = useState({
    full_name: '',
    department: '',
    role: 'faculty',
    email: '',
    contact: '',
    status: 'active'
  });
  const [message, setMessage] = useState({ type: '', text: '' });

  useEffect(() => {
    fetchFaculty();
  }, []);

  const fetchFaculty = async () => {
    try {
      setLoading(true);
      const response = await api.get('/people?role=faculty');
      setFaculty(response.data);
    } catch (error) {
      console.error('Error fetching faculty:', error);
      setMessage({ type: 'error', text: 'Error loading faculty.' });
    } finally {
      setLoading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      setLoading(true);
      const response = await api.post('/people', formData);
      setFaculty([...faculty, response.data]);
      setShowModal(false);
      setFormData({
        full_name: '',
        department: '',
        role: 'faculty',
        email: '',
        contact: '',
        status: 'active'
      });
      setMessage({ type: 'success', text: 'Faculty added successfully!' });
      setTimeout(() => setMessage({ type: '', text: '' }), 3000);
      fetchFaculty();
    } catch (error) {
      console.error('Error adding faculty:', error);
      setMessage({ type: 'error', text: 'Error adding faculty.' });
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (facultyMember) => {
    setSelectedFaculty(facultyMember);
    setFormData({
      full_name: facultyMember.full_name,
      department: facultyMember.department,
      role: facultyMember.role,
      email: facultyMember.email,
      contact: facultyMember.contact,
      status: facultyMember.status
    });
    setShowEditModal(true);
  };

  const handleUpdate = async (e) => {
    e.preventDefault();
    try {
      setLoading(true);
      const response = await api.put(`/people/${selectedFaculty.id}`, formData);
      const updatedFaculty = faculty.map(f => f.id === selectedFaculty.id ? response.data : f);
      setFaculty(updatedFaculty);
      setShowEditModal(false);
      setMessage({ type: 'success', text: 'Faculty updated successfully!' });
      setTimeout(() => setMessage({ type: '', text: '' }), 3000);
      fetchFaculty();
    } catch (error) {
      console.error('Error updating faculty:', error);
      setMessage({ type: 'error', text: 'Error updating faculty.' });
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id, name) => {
    if (window.confirm(`Are you sure you want to delete ${name}?`)) {
      try {
        setLoading(true);
        await api.delete(`/people/${id}`);
        setFaculty(faculty.filter(f => f.id !== id));
        setMessage({ type: 'success', text: 'Faculty deleted successfully!' });
        setTimeout(() => setMessage({ type: '', text: '' }), 3000);
        fetchFaculty();
      } catch (error) {
        console.error('Error deleting faculty:', error);
        setMessage({ type: 'error', text: 'Error deleting faculty.' });
      } finally {
        setLoading(false);
      }
    }
  };

  if (loading && faculty.length === 0) {
    return (
      <div className="flex">
        <Sidebar />
        <div className="ml-64 flex-1">
          <Header />
          <div className="p-8 flex items-center justify-center h-96">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex">
      <Sidebar />
      <div className="ml-64 flex-1">
        <Header />
        <div className="p-8 mt-16">
          {message.text && (
            <div className={`mb-4 p-4 rounded-lg ${
              message.type === 'success' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
            }`}>
              {message.text}
            </div>
          )}
          
          <div className="flex justify-between items-center mb-6">
            <h1 className="text-2xl font-bold text-gray-800">Faculty Management</h1>
            <button onClick={() => setShowModal(true)} className="bg-blue-600 text-white px-4 py-2 rounded-lg flex items-center gap-2">
              <UserPlus size={20} /> Add Faculty
            </button>
          </div>
          
          <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden">
            <table className="w-full">
              <thead className="bg-gray-50 border-b">
                <tr>
                  <th className="text-left p-4">Name</th>
                  <th className="text-left p-4">Department</th>
                  <th className="text-left p-4">Email</th>
                  <th className="text-left p-4">Contact</th>
                  <th className="text-left p-4">Status</th>
                  <th className="text-left p-4">Actions</th>
                </tr>
              </thead>
              <tbody>
                {faculty.map((member) => (
                  <tr key={member.id} className="border-b hover:bg-gray-50">
                    <td className="p-4 font-medium">{member.full_name}</td>
                    <td className="p-4">{member.department}</td>
                    <td className="p-4">{member.email}</td>
                    <td className="p-4">{member.contact || 'N/A'}</td>
                    <td className="p-4">
                      <span className={`px-2 py-1 rounded-full text-xs ${
                        member.status === 'active' ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'
                      }`}>{member.status}</span>
                    </td>
                    <td className="p-4">
                      <div className="flex gap-2">
                        <button onClick={() => handleEdit(member)} className="text-blue-600 hover:text-blue-800">
                          <Edit size={18} />
                        </button>
                        <button onClick={() => handleDelete(member.id, member.full_name)} className="text-red-600 hover:text-red-800">
                          <Trash2 size={18} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
      
      {/* Add Modal - Same as Students but with faculty role */}
      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-xl p-6 w-full max-w-md">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-xl font-bold">Add New Faculty</h2>
              <button onClick={() => setShowModal(false)}><X size={24} /></button>
            </div>
            <form onSubmit={handleSubmit}>
              <div className="space-y-4">
                <input type="text" placeholder="Full Name" value={formData.full_name}
                  onChange={(e) => setFormData({...formData, full_name: e.target.value})}
                  className="w-full p-2 border rounded-lg" required />
                <select value={formData.department} onChange={(e) => setFormData({...formData, department: e.target.value})}
                  className="w-full p-2 border rounded-lg" required>
                  <option value="">Select Department</option>
                  <option value="Computer Science">Computer Science</option>
                  <option value="Engineering">Engineering</option>
                  <option value="Physics">Physics</option>
                  <option value="Biology">Biology</option>
                  <option value="Mathematics">Mathematics</option>
                </select>
                <input type="email" placeholder="Email" value={formData.email}
                  onChange={(e) => setFormData({...formData, email: e.target.value})}
                  className="w-full p-2 border rounded-lg" required />
                <input type="text" placeholder="Contact" value={formData.contact}
                  onChange={(e) => setFormData({...formData, contact: e.target.value})}
                  className="w-full p-2 border rounded-lg" />
              </div>
              <div className="flex gap-2 mt-6">
                <button type="submit" className="flex-1 bg-blue-600 text-white py-2 rounded-lg">Add Faculty</button>
                <button type="button" onClick={() => setShowModal(false)} className="flex-1 bg-gray-200 py-2 rounded-lg">Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}
      
      {/* Edit Modal - Similar structure */}
      {showEditModal && selectedFaculty && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-xl p-6 w-full max-w-md">
            <h2 className="text-xl font-bold mb-4">Edit Faculty</h2>
            <form onSubmit={handleUpdate}>
              <div className="space-y-4">
                <input type="text" value={formData.full_name}
                  onChange={(e) => setFormData({...formData, full_name: e.target.value})}
                  className="w-full p-2 border rounded-lg" required />
                <select value={formData.department} onChange={(e) => setFormData({...formData, department: e.target.value})}
                  className="w-full p-2 border rounded-lg">
                  <option value="Computer Science">Computer Science</option>
                  <option value="Engineering">Engineering</option>
                  <option value="Physics">Physics</option>
                  <option value="Biology">Biology</option>
                </select>
                <input type="email" value={formData.email}
                  onChange={(e) => setFormData({...formData, email: e.target.value})}
                  className="w-full p-2 border rounded-lg" required />
                <input type="text" value={formData.contact}
                  onChange={(e) => setFormData({...formData, contact: e.target.value})}
                  className="w-full p-2 border rounded-lg" />
              </div>
              <div className="flex gap-2 mt-6">
                <button type="submit" className="flex-1 bg-blue-600 text-white py-2 rounded-lg">Update</button>
                <button type="button" onClick={() => setShowEditModal(false)} className="flex-1 bg-gray-200 py-2 rounded-lg">Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Faculty;
